// What ships by accident all over the industry:
try {
  throw 'invalid port';            // a raw string
} catch (e) {
  console.log(e instanceof Error); // false
  console.log(e.name);             // undefined — no name, no message, no stack
}

// What the engine itself throws — and what you should:
function setPort(value) {
  const port = Number(value);
  if (Number.isNaN(port)) {
    throw new TypeError('port must be a number, got ' + typeof value);
  }
  if (port < 0 || port > 65535) {
    throw new RangeError('port out of range: ' + port);
  }
  return port;
}

try { setPort('http'); } catch (e) { console.log(e.name + ': ' + e.message); }
// "TypeError: port must be a number, got string"
try { setPort(99999); } catch (e) { console.log(e.name + ': ' + e.message); }
// "RangeError: port out of range: 99999"

function loadSettings(raw) {
  try {
    return JSON.parse(raw);
  } catch (e) {
    // ES2022: attach the original error so the trail survives the re-throw
    throw new Error('settings could not be parsed', { cause: e });
  }
}

try {
  loadSettings("{'port': 8080}"); // single quotes — you know by now
} catch (e) {
  console.log(e.message);        // "settings could not be parsed"
  console.log(e.cause.name);     // "SyntaxError" — the original is still attached
}

// ES2019: no use for the caught value? Skip the binding entirely:
try { JSON.parse('nope'); } catch {
  console.log('rejected malformed input');
}

function readFile(path) {
  console.log('opening ' + path);
  try {
    if (path === 'missing.json') throw new Error('not found');
    return 'contents of ' + path;
  } catch (e) {
    console.log('caught: ' + e.message);
    return 'fallback contents';
  } finally {
    console.log('finally: closing the file — runs NO MATTER WHAT');
  }
}

console.log(readFile('config.json'));
// opening config.json
// finally: closing the file — runs NO MATTER WHAT
// contents of config.json

console.log(readFile('missing.json'));
// opening missing.json
// caught: not found
// finally: closing the file — runs NO MATTER WHAT
// fallback contents

const user = {
  id: 7,
  nickname: undefined,    // dropped — JSON has no undefined
  save: () => 'saved',    // dropped — JSON has no functions
  badge: Symbol('gold'),  // dropped — JSON has no symbols
  lastSeen: new Date(0),  // serialized via toISOString()
  score: NaN,             // becomes null
  streak: Infinity,       // becomes null
};
console.log(JSON.stringify(user));
// {"id":7,"lastSeen":"1970-01-01T00:00:00.000Z","score":null,"streak":null}

// Arrays follow a stricter rule: missing things become null, not dropped
console.log(JSON.stringify([1, undefined, 2]));  // [1,null,2]
console.log(JSON.stringify([() => 1, 'a']));     // [null,"a"]

// The loud failure — a circular reference throws:
const node = { name: 'root' };
node.self = node;
try { JSON.stringify(node); } catch (e) { console.log(e.name); }  // "TypeError"
// V8: "Converting circular structure to JSON" · JavaScriptCore words it differently

console.log(JSON.parse('{"dev": true}'));   // { dev: true } — the valid case

// Every one of these throws SyntaxError — the tiniest mistake is fatal:
const broken = [
  "{'dev': true}",    // single quotes — the classic API bug
  '{"dev": true,}',   // trailing comma — legal in JS literals, illegal in JSON
  '{dev: true}',      // unquoted key — legal in JS, illegal in JSON
];
for (const text of broken) {
  try { JSON.parse(text); } catch (e) { console.log(e.name); }
}

function safeParse(text) {
  try {
    return { ok: true, value: JSON.parse(text) };
  } catch (e) {
    return { ok: false, error: e.message };
  }
}

// The failure is now a VALUE your code can branch on — no crash:
const result = safeParse("{'dev': true}");
console.log(result.ok);     // false
console.log(result.error);  // the SyntaxError's message — wording depends on the engine

// The success path still carries the parsed data:
const fine = safeParse('{"dev": true}');
console.log(fine.ok, fine.value.dev);  // true true

