// 1) The classic crash, caught by hand — name + message:
try {
  JSON.parse("{'dev': true}"); // single quotes — invalid JSON
} catch (e) {
  console.log('1) caught ' + e.name + ' — ' + e.message);
}

// 2) The same call on valid JSON — an object comes back:
const parsed = JSON.parse('{"dev": true, "level": 2}');
console.log('2) parsed: ' + parsed.dev + ' ' + parsed.level);

// 3) The guard you will actually ship:
function safeParse(text) {
  try {
    return { ok: true, value: JSON.parse(text) };
  } catch (e) {
    return { ok: false, error: e.message };
  }
}

console.log('3) bad  → ' + JSON.stringify(safeParse("{'dev': true}")));
console.log('4) good → ' + JSON.stringify(safeParse('{"dev": true, "level": 2}')));

