function loadConfig(raw) {
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    return { ok: false, error: 'not valid JSON: ' + e.message };
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    return { ok: false, error: 'expected an object' };
  }
  if (typeof parsed.port !== 'number') {
    return { ok: false, error: 'missing or non-numeric field: port' };
  }
  return { ok: true, config: parsed };
}

const inputs = [
  ['valid',   '{"port": 8080, "host": "localhost"}'],
  ['broken',  "{'port': 8080}"],
  ['not-obj', '[8080, 9090]'],
  ['no-port', '{"host": "localhost"}'],
];
for (const [name, raw] of inputs) {
  console.log(name + ' -> ' + JSON.stringify(loadConfig(raw)));
}
// valid   -> {"ok":true,"config":{"port":8080,"host":"localhost"}}
// broken  -> {"ok":false,"error":"not valid JSON: …message varies by engine…"}
// not-obj -> {"ok":false,"error":"expected an object"}
// no-port -> {"ok":false,"error":"missing or non-numeric field: port"}

